# Quantum Victory 1.5.1 - mobile-safe Streamlit launcher
import base64, io, os, runpy, sys, zipfile
from pathlib import Path

PAYLOAD_B64 = """"""
ROOT = Path(__file__).resolve().parent
RUNTIME = ROOT / ".qv_runtime_1_5_1"
MARKER = RUNTIME / ".installed"
if not MARKER.exists():
    RUNTIME.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD_B64)), "r") as z:
        z.extractall(RUNTIME)
    MARKER.write_text("QV 1.5.1 READY", encoding="utf-8")
if str(RUNTIME) not in sys.path:
    sys.path.insert(0, str(RUNTIME))
os.environ.setdefault("QV_OFFLINE_MODE", "1")
runpy.run_path(str(RUNTIME / "streamlit_app.py"), run_name="__main__")
